# session-start: before /bootstrap records a test command, the preload names the repository's own test entry points; after it, the recorded command.
if (-not (Get-Command Invoke-Hook -ErrorAction SilentlyContinue)) { . (Join-Path $PSScriptRoot '_HookHarness.ps1') }
$hooks=(Resolve-Path (Join-Path $PSScriptRoot '..\..\.claude\hooks')).Path;$sessionStart=Join-Path $hooks 'session-start.ps1'
$label='**Unrecorded test entry points** (no Verification Commands recorded yet): '
$owned='{"schema-version":1,"paths":[{"path":"tests/evals/cases.yaml","ownership":"framework-owned/overwritten"},{"path":"scripts/test-weakening-scan.ps1","ownership":"framework-owned/overwritten"}]}'
function Put($p,$s){$d=Split-Path $p -Parent;if($d){New-Item -ItemType Directory -Force $d|Out-Null};[IO.File]::WriteAllText($p,$s,[Text.UTF8Encoding]::new($false))}
function Root([bool]$Pending=$true,[string[]]$Files=@('tests/Test-Calculator.ps1','tests/evals/cases.yaml'),[hashtable]$Content=@{},[bool]$Git=$true,$Ownership=$owned,$Retirements=$null){
    $r=Join-Path([IO.Path]::GetTempPath())('session-tests-'+[guid]::NewGuid());New-Item -ItemType Directory -Force $r|Out-Null
    Put (Join-Path $r 'AGENTS.md') ("# Fixture`n"+$(if($Pending){"BOOTSTRAP_PENDING`n"}else{''}))
    if($null -ne $Ownership){Put (Join-Path $r 'framework-ownership.json') $Ownership}
    if($null -ne $Retirements){Put (Join-Path $r 'framework-retirements.json') $Retirements}
    foreach($f in $Files){Put (Join-Path $r $f) $(if($Content.ContainsKey($f)){$Content[$f]}else{'x'})}
    if($Git){git -C $r init -q 2>$null;git -C $r add -A 2>$null};$r}
function RunAt($root,$event){Push-Location $root;try{Invoke-Hook (Copy-HookInto $sessionStart $root) $event}finally{Pop-Location}}
function Listed($o){$m=[regex]::Match($o.Out,[regex]::Escape($label)+'(.+?)\. Files, not recorded commands');if($m.Success){$m.Groups[1].Value}else{'none'}}
$claude='{"hook_event_name":"SessionStart","source":"startup"}';$copilot='{"source":"new","sessionId":"s","timestamp":1,"cwd":"."}'
Reset-Tests
It 'unbootstrapped: names the consumer test script and not the framework-owned files' {$r=Root -Files @('tests/Test-Calculator.ps1','tests/evals/cases.yaml','scripts/test-weakening-scan.ps1','src/Calculator.cs');try{$o=RunAt $r $claude;Assert($o.Exit-eq0)"hook crashed: $($o.Err)";Assert($o.Out.Contains($label+'tests/Test-Calculator.ps1.'))"line missing or wrong: $($o.Out)";Assert(-not($o.Out-match'tests/evals|test-weakening-scan'))"a framework-owned file was listed: $($o.Out)"}finally{Remove-Item -Recurse -Force $r}}
It 'bootstrapped: no line' {$r=Root -Pending $false;try{$o=RunAt $r $claude;Assert($o.Exit-eq0)'hook crashed';Assert(-not$o.Out.Contains('Unrecorded test entry points'))"line emitted for a bootstrapped repository: $($o.Out)"}finally{Remove-Item -Recurse -Force $r}}
It 'no test entry point: no line' {$r=Root -Files @('src/Calculator.cs','tests/evals/cases.yaml');try{$o=RunAt $r $claude;Assert($o.Exit-eq0)'hook crashed';Assert(-not$o.Out.Contains('Unrecorded test entry points'))"line emitted with only framework-owned tests: $($o.Out)"}finally{Remove-Item -Recurse -Force $r}}
It 'package.json counts only with a test script' {foreach($case in @(@('{"scripts":{"build":"tsc"}}','none'),@('{"devDependencies":{"test":"1.0.0"},"scripts":{"build":"tsc"}}','none'),@('{"scripts":{"test":',  'none'),@('{"scripts":{"test":"jest"}}','package.json'),@('{"scripts":{"test:unit":"jest"}}','package.json'))){$r=Root -Files @('package.json') -Content @{'package.json'=$case[0]};try{$o=RunAt $r $claude;Assert($o.Exit-eq0)'hook crashed';Assert((Listed $o)-eq$case[1])"package.json $($case[0]): listed '$(Listed $o)', expected '$($case[1])'"}finally{Remove-Item -Recurse -Force $r}}}
It 'dependency and build folders are skipped' {$r=Root -Files @('node_modules/lib/tests/a.js','src/App/bin/Debug/tests/b.ps1','tests/run.ps1');try{$o=RunAt $r $claude;Assert((Listed $o)-eq'tests/run.ps1')"expected only tests/run.ps1: $(Listed $o)"}finally{Remove-Item -Recurse -Force $r}}
It 'at most eight are named, then "and more"' {$r=Root -Files @(1..10|ForEach-Object{"tests/t$_.ps1"});try{$o=RunAt $r $claude;Assert($o.Out-match[regex]::Escape($label)+'(?:tests/t\d+\.ps1, ){7}tests/t\d+\.ps1 \(and more\)\.')"cap not applied: $($o.Out)"}finally{Remove-Item -Recurse -Force $r}}
It 'not a git repository: silent, no crash' {$r=Root -Git $false;try{$o=RunAt $r $claude;Assert($o.Exit-eq0)"hook crashed: $($o.Err)";Assert(-not$o.Out.Contains('Unrecorded test entry points'))'line emitted outside a git repository'}finally{Remove-Item -Recurse -Force $r}}
It 'an install in a subfolder of the repository still gets the branch, recent commits, test entry points and debt heat' {
    $r=Root -Git $false -Files @('tests/Test-Calculator.ps1','tests/evals/cases.yaml','TECH_DEBT.md') -Content @{'TECH_DEBT.md'="- tests/Test-Calculator.ps1 is slow`n"}
    $outer=$r+'-outer';New-Item -ItemType Directory -Force $outer|Out-Null;$app=Join-Path $outer 'app';Move-Item -LiteralPath $r -Destination $app
    try{
        git -C $outer init -q 2>$null;git -C $outer add -A 2>$null;git -C $outer -c user.name=fixture -c user.email=fixture@example.invalid commit -q -m 'subfolder fixture' 2>$null
        $branch=[string](git -C $outer rev-parse --abbrev-ref HEAD 2>$null)
        $o=RunAt $app $claude
        Assert($o.Exit-eq0)"hook crashed: $($o.Err)"
        Assert($o.Out.Contains("- **Branch:** ``$branch``")-and$o.Out.Contains('subfolder fixture'))"branch or recent commits missing: $($o.Out)"
        Assert((Listed $o)-eq'tests/Test-Calculator.ps1')"expected the test entry point relative to the install folder, got '$(Listed $o)': $($o.Out)"
        Assert($o.Out.Contains('- **Debt heat:** 1 TECH_DEBT entry'))"debt heat missing, or counted against repository-root paths: $($o.Out)"
    }finally{Remove-Item -Recurse -Force $outer}}
It 'a repository with no commit yet reports an unknown branch and leaves git''s fatal lines off stderr' {$r=Root -Files @('tests/Test-Calculator.ps1','TECH_DEBT.md');try{$o=RunAt $r $claude;Assert($o.Exit-eq0)"hook crashed: $($o.Err)";Assert($o.Out.Contains('- **Branch:** `(unknown)`'))"expected an unknown branch: $($o.Out)";Assert($o.Err-eq'')"git's output reached stderr: $($o.Err)"}finally{Remove-Item -Recurse -Force $r}}
It 'Copilot JSON carries the line in both shapes' {$r=Root;try{$o=RunAt $r $copilot;Assert($o.Exit-eq0)'hook crashed';$j=($o.Out|ConvertFrom-Json);Assert(([string]$j.additionalContext).Contains($label+'tests/Test-Calculator.ps1.'))'top-level additionalContext lacks the line';Assert(([string]$j.hookSpecificOutput.additionalContext).Contains($label+'tests/Test-Calculator.ps1.'))'hookSpecificOutput lacks the line'}finally{Remove-Item -Recurse -Force $r}}
It 'retired framework test files are never listed' {$r=Root -Files @('tests/hooks/Guard.Tests.ps1','tests/hooks/_HookHarness.ps1','tests/run.ps1') -Retirements '{"schema-version":1,"retirements":[{"path":"tests/hooks/Guard.Tests.ps1","retired-in":"0.81.0"},{"path":"tests/hooks/_HookHarness.ps1","retired-in":"0.81.0"}]}';try{$o=RunAt $r $claude;Assert((Listed $o)-eq'tests/run.ps1')"a retired framework file was listed: $(Listed $o)"}finally{Remove-Item -Recurse -Force $r}}
It 'a missing or unreadable ownership manifest lists nothing' {foreach($own in @($null,'{"paths":[',' ')){$r=Root -Ownership $own;try{$o=RunAt $r $claude;Assert($o.Exit-eq0)"hook crashed: $($o.Err)";Assert((Listed $o)-eq'none')"ownership '$own' listed: $(Listed $o)"}finally{Remove-Item -Recurse -Force $r}}}
It 'non-ASCII names are real paths and still filtered' {$r=Root -Files @("tests/t$([char]0xEB)st_$([char]0xFC).ps1","tests/fr$([char]0xE4)m.ps1","node_modules/pkg$([char]0xE9)/tests/x.js") -Ownership ('{"paths":[{"path":"tests/fr'+[char]0xE4+'m.ps1","ownership":"framework-owned/overwritten"}]}');try{$o=RunAt $r $claude;Assert((Listed $o)-ceq"tests/t$([char]0xEB)st_$([char]0xFC).ps1")"expected only the unquoted consumer file: $(Listed $o)"}finally{Remove-Item -Recurse -Force $r}}
It 'a script outside test folders is not offered as a test' {$r=Root -Files @('src/IntegrationTests/Deploy-Database.ps1','build/TestData/publish.ps1','scripts/Get-Latest.ps1','tests/run.ps1','src/Calc.Tests/Calc.Tests.csproj');try{$o=RunAt $r $claude;Assert((Listed $o)-eq'src/Calc.Tests/Calc.Tests.csproj, tests/run.ps1')"unexpected list: $(Listed $o)"}finally{Remove-Item -Recurse -Force $r}}
It 'a tracked test file deleted from the working tree is not listed' {$r=Root -Files @('tests/gone.ps1','tests/run.ps1');try{Remove-Item (Join-Path $r 'tests/gone.ps1');$o=RunAt $r $claude;Assert((Listed $o)-eq'tests/run.ps1')"a deleted file was listed: $(Listed $o)"}finally{Remove-Item -Recurse -Force $r}}
It 'an ownership manifest that lists no paths lists nothing, whatever the retirements file holds' {foreach($own in @('{}','{"schema-version":2,"files":[{"path":"tests/evals/cases.yaml"}]}','{"paths":[{"file":"tests/evals/cases.yaml"}]}')){$r=Root -Ownership $own -Retirements '{"retirements":[{"path":"tests/hooks/Guard.Tests.ps1","retired-in":"0.81.0"}]}';try{$o=RunAt $r $claude;Assert($o.Exit-eq0)'hook crashed';Assert((Listed $o)-eq'none')"ownership '$own' listed: $(Listed $o)"}finally{Remove-Item -Recurse -Force $r}}}
It 'test projects and scripts come before other files under test folders' {$r=Root -Files (@(1..10|ForEach-Object{"tests/Contoso.Api.Tests/A$($_)Tests.cs"})+@('tests/Contoso.Api.Tests/Contoso.Api.Tests.csproj'));try{$o=RunAt $r $claude;Assert((Listed $o)-like'tests/Contoso.Api.Tests/Contoso.Api.Tests.csproj, *')"the test project is not listed first: $(Listed $o)"}finally{Remove-Item -Recurse -Force $r}}
It 'a UnitTests or IntegrationTests project outside a tests folder is listed' {$r=Root -Files @('src/X.UnitTests/X.UnitTests.csproj','src/X.IntegrationTests/X.IntegrationTests.csproj','src/X/X.csproj');try{$o=RunAt $r $claude;Assert((Listed $o)-eq'src/X.IntegrationTests/X.IntegrationTests.csproj, src/X.UnitTests/X.UnitTests.csproj')"unexpected list: $(Listed $o)"}finally{Remove-Item -Recurse -Force $r}}
It 'capitalised dependency and build folders are skipped too' {$r=Root -Files @('Node_Modules/p/tests/a.js','src/App/Bin/Debug/tests/b.ps1','src/App/Obj/tests/c.ps1','tests/run.ps1');try{$o=RunAt $r $claude;Assert((Listed $o)-eq'tests/run.ps1')"expected only tests/run.ps1: $(Listed $o)"}finally{Remove-Item -Recurse -Force $r}}
It 'a "Test" script npm would ignore does not count' {$r=Root -Files @('package.json') -Content @{'package.json'='{"scripts":{"Test":"jest"}}'};try{$o=RunAt $r $claude;Assert((Listed $o)-eq'none')"capital-T Test was listed: $(Listed $o)"}finally{Remove-Item -Recurse -Force $r}}
$recorded='- **Recorded test command:** `pwsh -NoProfile -File tests/Test-Calculator.ps1` (`AGENTS.md` '+[char]0x203A+' Verification Commands). For a bug fix, before any production edit, run it alone, with no other tool call in the same turn, and see the failing case fail: an edit sent in that turn can land first and hide the red.'
function Bootstrapped([string]$TestCell,[bool]$Pending=$false){"# Fixture`n$(if($Pending){"BOOTSTRAP_PENDING`n"})`n## Conventions`n`n### Verification Commands`n`n| Category | Command | Evidence | Execution policy |`n|----------|---------|----------|------------------|`n| build | ``dotnet build App.csproj`` | ``App.csproj`` | safe to run |`n| test | $TestCell | ``tests/Test-Calculator.ps1`` | safe to run |`n`n## Architecture Decisions`n"}
It 'bootstrapped with a recorded test command: one line names it, on both surfaces' {$r=Root -Pending $false -Files @('AGENTS.md','tests/Test-Calculator.ps1') -Content @{'AGENTS.md'=(Bootstrapped '`pwsh -NoProfile -File tests/Test-Calculator.ps1`')};try{$o=RunAt $r $claude;Assert($o.Exit-eq0)"hook crashed: $($o.Err)";$l=@($o.Out-split"`n"|Where-Object{$_-like'- **Recorded test command*'});Assert($l.Count-eq1-and$l[0]-ceq$recorded)"expected the one line, got: $($l -join ' / ')";$c=RunAt $r $copilot;$j=($c.Out|ConvertFrom-Json);Assert(([string]$j.additionalContext).Contains($recorded)-and([string]$j.hookSpecificOutput.additionalContext).Contains($recorded))'a Copilot JSON shape lacks the line'}finally{Remove-Item -Recurse -Force $r}}
It 'no recorded test command, or not bootstrapped: no recorded-command line' {foreach($agents in @((Bootstrapped 'not available (no evidenced command)'),"# Fixture`n",(Bootstrapped '`pwsh -NoProfile -File tests/Test-Calculator.ps1`' $true))){$r=Root -Pending $false -Files @('AGENTS.md','tests/Test-Calculator.ps1') -Content @{'AGENTS.md'=$agents};try{$o=RunAt $r $claude;Assert($o.Exit-eq0)"hook crashed: $($o.Err)";Assert(-not$o.Out.Contains('Recorded test command'))"line emitted for: $agents"}finally{Remove-Item -Recurse -Force $r}}}
exit(Write-TestSummary 'SessionStartTestEntryPoints.Tests')
